import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void depthwise_kx1_conv2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    const int N,
    const int C,
    const int H,
    const int W,
    const int Ho,
    const int Wo,
    const int K,
    const int stride,
    const int padding,
    const int dilation,
    const bool has_bias) {
  const long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
  const long long total = (long long)N * C * Ho * Wo;
  if (idx >= total) return;

  const int ow = (int)(idx % Wo);
  long long t = idx / Wo;
  const int oh = (int)(t % Ho);
  t /= Ho;
  const int c = (int)(t % C);
  const int n = (int)(t / C);

  const float* x_nc = x + (((long long)n * C + c) * H) * W + ow;
  const float* w_c = w + (long long)c * K;

  float acc = 0.0f;
#pragma unroll
  for (int kh = 0; kh < 8; ++kh) {
    if (kh < K) {
      const int ih = oh * stride + kh * dilation - padding;
      if (ih >= 0 && ih < H) {
        acc += x_nc[(long long)ih * W] * w_c[kh];
      }
    }
  }

  if (has_bias) acc += b[c];
  y[idx] = acc;
}

torch::Tensor depthwise_kx1_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation) {
  TORCH_CHECK(x.is_cuda(), "input must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.dim() == 4, "input must be NCHW");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 is supported");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "only float32 is supported");

  const c10::cuda::CUDAGuard device_guard(x.device());

  auto xc = x.contiguous();
  auto wc = weight.contiguous();

  const int N = (int)xc.size(0);
  const int C = (int)xc.size(1);
  const int H = (int)xc.size(2);
  const int W = (int)xc.size(3);

  TORCH_CHECK(wc.dim() == 4, "weight must be (C,1,K,1)");
  TORCH_CHECK(wc.size(0) == C, "depthwise weight channels mismatch");
  TORCH_CHECK(wc.size(1) == 1, "depthwise weight must have one input channel");
  TORCH_CHECK(wc.size(3) == 1, "only Kx1 kernels are supported");
  const int K = (int)wc.size(2);
  TORCH_CHECK(K <= 8, "kernel height must be <= 8");

  const int Ho = (int)((H + 2 * padding - dilation * (K - 1) - 1) / stride + 1);
  const int Wo = (int)((W + 2 * padding - 1) / stride + 1);

  auto y = torch::empty({N, C, Ho, Wo}, xc.options());
  const long long total = (long long)N * C * Ho * Wo;
  if (total == 0) return y;

  const float* bptr = nullptr;
  torch::Tensor bc;
  if (has_bias) {
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(bias.scalar_type() == at::kFloat, "only float32 is supported");
    TORCH_CHECK(bias.numel() == C, "bias size mismatch");
    bc = bias.contiguous();
    bptr = bc.data_ptr<float>();
  }

  const int threads = 256;
  const unsigned int blocks = (unsigned int)((total + threads - 1) / threads);
  depthwise_kx1_conv2d_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
      xc.data_ptr<float>(),
      wc.data_ptr<float>(),
      bptr,
      y.data_ptr<float>(),
      N, C, H, W, Ho, Wo, K,
      (int)stride, (int)padding, (int)dilation,
      has_bias);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""

_cpp_src = r"""
torch::Tensor depthwise_kx1_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation);
"""

_depthwise_kx1_ext = load_inline(
    name="depthwise_kx1_conv2d_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["depthwise_kx1_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(
            in_channels,
            in_channels,
            kernel_size=(kernel_size, 1),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=in_channels,
            bias=bias,
        )
        self.stride = self.conv2d.stride[0]
        self.padding = self.conv2d.padding[0]
        self.dilation = self.conv2d.dilation[0]

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.to(self.conv2d.weight.device)
        if self.conv2d.bias is None:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)
            has_bias = False
        else:
            bias = self.conv2d.bias
            has_bias = True
        return _depthwise_kx1_ext.depthwise_kx1_forward(
            x,
            self.conv2d.weight,
            bias,
            has_bias,
            self.stride,
            self.padding,
            self.dilation,
        )

